steps.text:
/*
	VIOC_killcam.sqf - parche killcam de VIOC (2026-10-21). No es del autor de la mision.
	Camara post-impacto para los drones que el jugador vuela con la terminal UAV: Crocus de ArmaFPV, Mavic 3 Improved y
	cualquier dron pequenio tipo helicoptero (unitIsUAV). Lo lanza init.sqf en las maquinas con jugador; nada en el servidor.
	Parametros de lobby VIOC_KILLCAM (0 = no, 1 = si) y VIOC_KILLCAM_TIME (s, al menos 60).

	Accion en el dron conectado (y en el jugador mientras tiene un dron conectado sin controlarlo):
	"Camara post-impacto: activar / desactivar" (por dron). Si esta activada y el dron se destruye o desaparece (el FPV
	estalla y el mod lo borra) mientras estaba conectado, tras 1 s (se pierde la senial) un "dron" ficticio a VIOC_KC_ALT m
	sobre el punto de impacto da vueltas alrededor durante VIOC_KILLCAM_TIME s con interfaz de dron: REC, tiempo, altitud,
	distancia, rumbo, cuadricula y la evaluacion del danio (BDA) a VIOC_KC_BDA_R m del impacto: vehiculos destruidos o
	daniados y bajas (propias aparte). Al terminar desaparece y no se puede volver a abrir.
	No es un objeto: es una camara local (camCreate). Nadie la ve, la IA no la detecta ni la ataca.
	Teclas: ESPACIO sale antes; N cambia la vision (normal, nocturna, termica). Se corta si el jugador muere o recibe danio.
	Consola (LOCAL EXEC), prueba sin dron: [getPosATL player, []] spawn VIOC_KC_fnc_run;
*/
if (!hasInterface) exitWith {};
waitUntil {sleep 1; !isNull player && {!isNil "CTI_InitClient"}};	//--- parametros del lobby y jugador listos
if ((missionNamespace getVariable ["VIOC_KILLCAM", 1]) <= 0) exitWith {};

VIOC_KC_TIME = (missionNamespace getVariable ["VIOC_KILLCAM_TIME", 60]) max 60;
VIOC_KC_ALT = 40;      // m sobre el suelo del punto de impacto
VIOC_KC_RAD = 70;      // m: radio del circulo
VIOC_KC_LAP = 50;      // s por vuelta
VIOC_KC_BDA_R = 25;    // m: radio de la evaluacion de danio
VIOC_KC_BUSY = false;
VIOC_KC_EXIT = false;
VIOC_KC_VIS = 0;

//--- [objeto] -> true si es un dron pequenio (cuadricoptero) que se vuela con la terminal UAV
VIOC_KC_fnc_isDrone = {
	params ["_d"];
	!isNull _d && {unitIsUAV _d} && {_d isKindOf "Helicopter"}
};

//--- [dron]: acciones activar/desactivar en el dron (se ven al controlarlo)
VIOC_KC_fnc_droneActions = {
	params ["_d"];
	if (_d getVariable ["vioc_kc_act", false]) exitWith {};
	_d setVariable ["vioc_kc_act", true];
	_d addAction ["<t color='#ffb000'>Camara post-impacto: activar</t>", {(_this select 0) setVariable ["vioc_kc", true]; call VIOC_KC_fnc_onMsg},
		nil, 0.5, false, true, "", "!(_target getVariable ['vioc_kc', false])", -1];
	_d addAction ["<t color='#ffb000'>Camara post-impacto: desactivar</t>", {(_this select 0) setVariable ["vioc_kc", false]; systemChat "Camara post-impacto desactivada."},
		nil, 0.5, false, true, "", "_target getVariable ['vioc_kc', false]", -1];
};

VIOC_KC_fnc_onMsg = {
	systemChat format ["Camara post-impacto activada: si el dron estalla, otro dron a %1 m mostrara el resultado durante %2 s (ESPACIO sale, N cambia la vision).", VIOC_KC_ALT, VIOC_KC_TIME];
};

//--- acciones en el jugador (dron conectado pero sin controlarlo); se vuelven a poner al reaparecer
VIOC_KC_fnc_playerActions = {
	params [["_u", player]];
	_u addAction ["<t color='#ffb000'>Camara post-impacto del dron: activar</t>", {(getConnectedUAV player) setVariable ["vioc_kc", true]; call VIOC_KC_fnc_onMsg},
		nil, 0.4, false, true, "", "_this == _target && {[getConnectedUAV _target] call VIOC_KC_fnc_isDrone} && {!((getConnectedUAV _target) getVariable ['vioc_kc', false])}"];
	_u addAction ["<t color='#ffb000'>Camara post-impacto del dron: desactivar</t>", {(getConnectedUAV player) setVariable ["vioc_kc", false]; systemChat "Camara post-impacto desactivada."},
		nil, 0.4, false, true, "", "_this == _target && {[getConnectedUAV _target] call VIOC_KC_fnc_isDrone} && {(getConnectedUAV _target) getVariable ['vioc_kc', false]}"];
};

//--- [objeto] -> danio maximo (general o de cualquier punto de impacto)
VIOC_KC_fnc_dmg = {
	params ["_o"];
	private _h = getAllHitPointsDamage _o;
	if (_h isEqualTo [] || {(_h select 2) isEqualTo []}) exitWith {damage _o};
	selectMax ((_h select 2) + [damage _o])
};

//--- [posicion ATL] -> [[objeto, danio, es hombre, bando]] vivos cerca (tripulaciones incluidas), sin el jugador ni drones
VIOC_KC_fnc_snap = {
	params ["_p"];
	private _r = [];
	{
		if (alive _x && {_x != player} && {!unitIsUAV _x}) then {
			_r pushBack [_x, [_x] call VIOC_KC_fnc_dmg, _x isKindOf "CAManBase", side (group _x)];
			if !(_x isKindOf "CAManBase") then {
				{ if (alive _x && {_x != player}) then {_r pushBack [_x, [_x] call VIOC_KC_fnc_dmg, true, side (group _x)]} } forEach (crew _x);
			};
		};
	} forEach (_p nearEntities [["CAManBase", "LandVehicle", "Air", "Ship", "StaticWeapon"], VIOC_KC_BDA_R]);
	_r
};

//--- [foto previa] -> texto de la evaluacion de danio
VIOC_KC_fnc_bda = {
	params ["_snap"];
	private _vk = 0; private _vd = 0; private _mk = 0; private _mw = 0; private _own = 0;
	{
		_x params ["_o", "_d0", "_man", "_s"];
		private _dead = isNull _o || {!alive _o};
		if (_man) then {
			if (_dead) then {_mk = _mk + 1; if (_s == playerSide) then {_own = _own + 1}} else {if (([_o] call VIOC_KC_fnc_dmg) > _d0 + 0.05) then {_mw = _mw + 1}};	//--- misma medida que la foto previa
		} else {
			if (_dead) then {_vk = _vk + 1} else {if (([_o] call VIOC_KC_fnc_dmg) > _d0 + 0.05) then {_vd = _vd + 1}};
		};
	} forEach _snap;
	private _l = [];
	if (_vk > 0) then {_l pushBack format ["%1 vehiculo(s) destruido(s)", _vk]};
	if (_vd > 0) then {_l pushBack format ["%1 vehiculo(s) daniado(s)", _vd]};
	if (_mk > 0) then {_l pushBack format ["%1 baja(s)", _mk]};
	if (_mw > 0) then {_l pushBack format ["%1 herido(s)", _mw]};
	if (_l isEqualTo []) exitWith {format ["<t color='#ff5050'>SIN EFECTOS a %1 m: FALLO</t>", VIOC_KC_BDA_R]};
	private _t = "<t color='#60ff60'>IMPACTO: " + (_l joinString ", ") + "</t>";
	if (_own > 0) then {_t = _t + format [" <t color='#ff5050'>(propias: %1)</t>", _own]};
	_t
};

//--- [posicion ATL del impacto, foto previa]: la camara del dron ficticio
VIOC_KC_fnc_run = {
	params ["_pos", ["_snap", []]];
	if (VIOC_KC_BUSY) exitWith {};
	VIOC_KC_BUSY = true;
	VIOC_KC_EXIT = false;
	VIOC_KC_VIS = 0;
	private _c = [_pos select 0, _pos select 1, 0];
	private _zc = getTerrainHeightASL _c;
	private _fnc_camPos = {
		params ["_a"];
		private _p = _c getPos [VIOC_KC_RAD, _a];
		_p set [2, ((_zc + VIOC_KC_ALT) - (getTerrainHeightASL _p)) max 15];
		_p
	};
	private _a = random 360;
	private _cam = "camera" camCreate ([_a] call _fnc_camPos);
	_cam cameraEffect ["internal", "back"];
	_cam camSetTarget _c;
	_cam camSetFov 0.55;
	_cam camCommit 0;
	showCinemaBorder false;
	private _grain = ppEffectCreate ["FilmGrain", 2005];
	_grain ppEffectEnable true;
	_grain ppEffectAdjust [0.12, 1, 1, 0.5, 0.5, true];
	_grain ppEffectCommit 0;
	//--- interfaz de dron
	private _layer = "VIOC_KC" call BIS_fnc_rscLayer;
	_layer cutRsc ["RscTitleDisplayEmpty", "PLAIN", 0, false];
	private _disp = uiNamespace getVariable ["RscTitleDisplayEmpty", displayNull];
	private _fnc_ctl = {
		params ["_cls", "_x0", "_y0", "_w", "_h"];
		private _ct = _disp ctrlCreate [_cls, -1];
		_ct ctrlSetPosition [_x0, _y0, _w, _h];
		_ct ctrlCommit 0;
		_ct
	};
	private _sx = safeZoneX; private _sy = safeZoneY; private _sw = safeZoneW; private _sh = safeZoneH;
	private _frame = ["RscFrame", _sx + 0.03 * _sw, _sy + 0.04 * _sh, 0.94 * _sw, 0.92 * _sh] call _fnc_ctl;
	_frame ctrlSetTextColor [1, 1, 1, 0.5];
	private _tl = ["RscStructuredText", _sx + 0.04 * _sw, _sy + 0.05 * _sh, 0.45 * _sw, 0.05 * _sh] call _fnc_ctl;
	private _tr = ["RscStructuredText", _sx + 0.51 * _sw, _sy + 0.05 * _sh, 0.45 * _sw, 0.05 * _sh] call _fnc_ctl;
	private _cross = ["RscStructuredText", 0.5 - 0.1, 0.5 - 0.035, 0.2, 0.07] call _fnc_ctl;
	_cross ctrlSetStructuredText parseText "<t align='center' size='1.6' color='#d0ffffff'>[ + ]</t>";
	private _bda = ["RscStructuredText", _sx + 0.1 * _sw, _sy + 0.83 * _sh, 0.8 * _sw, 0.05 * _sh] call _fnc_ctl;
	private _bl = ["RscStructuredText", _sx + 0.04 * _sw, _sy + 0.89 * _sh, 0.6 * _sw, 0.05 * _sh] call _fnc_ctl;
	_bl ctrlSetStructuredText parseText "<t size='0.9' color='#c0ffffff'>ESPACIO: salir    N: vision</t>";
	VIOC_KC_KEY = (findDisplay 46) displayAddEventHandler ["KeyDown", {
		params ["", "_k"];
		if (_k == 57) exitWith {VIOC_KC_EXIT = true; true};
		if (_k == 49) exitWith {VIOC_KC_VIS = (VIOC_KC_VIS + 1) mod 3; true};
		false
	}];
	private _t0 = time;
	private _end = _t0 + VIOC_KC_TIME;
	private _d0 = damage player;
	private _vis = -1;
	private _bdaT = 0;
	private _bdaTxt = "<t color='#ffffff'>EVALUANDO IMPACTO...</t>";
	while {time < _end && {!VIOC_KC_EXIT} && {alive player} && {(damage player) <= _d0 + 0.01}} do {
		_a = _a + (360 / VIOC_KC_LAP) * 0.1;
		_cam camSetPos ([_a] call _fnc_camPos);
		_cam camCommit 0.1;
		if (_vis != VIOC_KC_VIS) then {
			_vis = VIOC_KC_VIS;
			camUseNVG (_vis == 1);
			if (_vis == 2) then {true setCamUseTI 0} else {false setCamUseTI 0};
		};
		if (time > _t0 + 2 && {time > _bdaT}) then {_bdaT = time + 1; _bdaTxt = [_snap] call VIOC_KC_fnc_bda};
		private _left = (_end - time) max 0;
		private _rec = if ((floor (time * 2)) mod 2 == 0) then {"<t color='#ff3030'>REC</t>"} else {"<t color='#00000000'>REC</t>"};
		_tl ctrlSetStructuredText parseText format ["<t size='1' font='EtelkaMonospacePro'>KILL CAM  UAV-2  %1  %2:%3</t>", _rec,
			floor (_left / 60), [str (floor (_left mod 60)), "0" + str (floor (_left mod 60))] select ((_left mod 60) < 10)];
		private _cp = getPosASL _cam;
		_tr ctrlSetStructuredText parseText format ["<t size='1' align='right' font='EtelkaMonospacePro'>ALT %1 M  DIST %2 M  RUMBO %3  CUAD %4  %5</t>",
			round ((_cp select 2) - _zc), round (_cam distance _c), round ((_cam getDir _c) mod 360), mapGridPosition _c, ["NORMAL", "NV", "TERMICA"] select _vis];
		_bda ctrlSetStructuredText parseText ("<t align='center' size='1.1'>" + _bdaTxt + "</t>");
		sleep 0.1;
	};
	//--- fin: el dron ficticio desaparece
	(findDisplay 46) displayRemoveEventHandler ["KeyDown", VIOC_KC_KEY];
	_layer cutText ["", "PLAIN"];
	camUseNVG false;
	false setCamUseTI 0;
	_grain ppEffectEnable false;
	ppEffectDestroy _grain;
	_cam cameraEffect ["terminate", "back"];
	camDestroy _cam;
	VIOC_KC_BUSY = false;
};

call VIOC_KC_fnc_playerActions;
player addEventHandler ["Respawn", {[_this select 0] call VIOC_KC_fnc_playerActions}];

//--- vigilancia: el ultimo dron conectado, su posicion y lo que hay cerca (si tiene la camara activada)
[] spawn {
	waitUntil {sleep 1; !isNull player};
	private _d = objNull; private _on = false; private _pos = []; private _snap = []; private _seen = -100; private _ts = 0;
	while {true} do {
		private _cu = getConnectedUAV player;
		if ([_cu] call VIOC_KC_fnc_isDrone) then {
			if (_cu isNotEqualTo _d) then {_d = _cu; _pos = []; _snap = []; [_d] call VIOC_KC_fnc_droneActions};
			_seen = time;
		};
		if (!isNull _d && {alive _d}) then {
			_on = _d getVariable ["vioc_kc", false];
			_pos = getPosATL _d;
			if (_on && {time > _ts}) then {_ts = time + 0.5; _snap = [_pos] call VIOC_KC_fnc_snap};
		} else {
			if (_on && {_pos isNotEqualTo []} && {(time - _seen) < 3} && {!VIOC_KC_BUSY} && {alive player}) then {
				[_pos, _snap] spawn {sleep 1; _this call VIOC_KC_fnc_run};
			};
			_d = objNull; _on = false; _pos = []; _snap = [];
		};
		sleep 0.1;
	};
};
diag_log "[VIOC killcam] activo";

class VIOC_KILLCAM {
	title = "VIOC drones: Camara post-impacto (accion en el dron: si estalla, otro dron ficticio muestra el resultado)";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};
class VIOC_KILLCAM_TIME {
	title = "VIOC drones: Duracion de la camara post-impacto";
	values[] = {60,90,120};
	texts[] = {"1 min","1.5 min","2 min"};
	default = 60;
};
